import{_ as t}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as r,o as e,c as i,a2 as l}from"./chunks/framework.z3u3TMv0.js";const _=JSON.parse('{"title":"欢迎","description":"MiniTavern Ultra（超迷你酒馆）——创造 AI 伙伴，演你的故事。导入或创建角色卡，自备模型开聊。","frontmatter":{"title":"欢迎","description":"MiniTavern Ultra（超迷你酒馆）——创造 AI 伙伴，演你的故事。导入或创建角色卡，自备模型开聊。","head":[["meta",{"name":"keywords","content":"AI角色扮演,AI伙伴,AI朋友,角色卡,虚拟伴侣,MiniTavern,超迷你酒馆"}],["meta",{"property":"og:title","content":"欢迎 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra（超迷你酒馆）——创造 AI 伙伴，演你的故事。导入或创建角色卡，自备模型开聊。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/"}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786517442000}'),n={name:"index.md"};function o(s,a,d,u,g,h){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="欢迎" tabindex="-1">欢迎 <a class="header-anchor" href="#欢迎" aria-label="Permalink to &quot;欢迎&quot;">​</a></h1><div class="overview-hero"><p><img src="'+t+'" alt="MiniTavern Ultra 功能界面展示"></p></div><h2 id="应用简介" tabindex="-1">应用简介 <a class="header-anchor" href="#应用简介" aria-label="Permalink to &quot;应用简介&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong>（超迷你酒馆）是一款 <strong>AI 角色扮演聊天应用</strong>。</p><p><strong>创造 AI 伙伴，演你的故事</strong>——从一张角色卡开始，选你想要的打开方式。</p><p>导入或创建角色，使用你自己的云端 API 或本地模型开聊。密钥与数据优先留在本机。</p><h2 id="你可以做什么" tabindex="-1">你可以做什么 <a class="header-anchor" href="#你可以做什么" aria-label="Permalink to &quot;你可以做什么&quot;">​</a></h2><ol><li><p><strong>创造属于自己的 AI 伙伴</strong><br> 自定义性格、说话方式与关系设定，让对方像「只懂你」的存在。适合倾诉、陪伴、日常闲聊。</p></li><li><p><strong>把爱豆、原作角色「带回身边」</strong><br> 导入社区角色卡（兼容 SillyTavern 常见规范），用你熟悉的语气继续剧情或日常互动。</p></li><li><p><strong>一起演故事、写长线剧情</strong><br> 用世界书稳住设定，用正则打磨展示效果；会话可单独绑定模型与外观，沉浸感由你掌控。</p></li><li><p><strong>用自己的模型，按自己的节奏</strong><br><strong>BYOK</strong>：自备 API Key 直连主流服务；也可以接家里电脑上的 Ollama / LM Studio。没有付费额度时见 <a href="/ultra_guides/free-cloud/">免费云端</a>；本机部署见 <a href="/ultra_guides/local/">部署本地模型</a>。</p></li></ol><h2 id="为什么是-minitavern" tabindex="-1">为什么是 MiniTavern <a class="header-anchor" href="#为什么是-minitavern" aria-label="Permalink to &quot;为什么是 MiniTavern&quot;">​</a></h2><ul><li><strong>一张卡，两种打开方式</strong>：日常陪伴或入戏扮演，同一入口</li><li><strong>角色卡优先</strong>：PNG / JSON 导入与预览，创作与开聊一条线打通</li><li><strong>私有 API</strong>：密钥自控，不被单一渠道锁死</li><li><strong>进阶可玩</strong>：世界书、正则、人设、互动卡面</li><li><strong>数据可带走</strong>：备份与单聊存档，换机不慌</li></ul><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li><strong>配置模型</strong>：设置 → <a href="/ultra_guides/manual/model-link">模型</a> → 模型连接 → 新建并测连，设为默认。</li><li><strong>导入或创造角色</strong>：角色卡 → <a href="/ultra_guides/manual/chara-card">导入或创建</a>。</li><li><strong>开始聊天</strong>：从角色开聊——陪伴或入戏，由你决定。</li></ol><p>更细步骤见 <a href="/ultra_guides/manual/getting-started">第一次使用</a>。本机部署见左侧 <strong>部署本地模型</strong>：<a href="/ultra_guides/local/">概览</a> · <a href="/ultra_guides/quickstart">语言模型通关</a> · <a href="/ultra_guides/local/image-gen/">生图</a>。免费额度见 <a href="/ultra_guides/free-cloud/">免费云端</a>。</p><h2 id="用户手册入口" tabindex="-1">用户手册入口 <a class="header-anchor" href="#用户手册入口" aria-label="Permalink to &quot;用户手册入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分区</th><th>说明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/manual/">手册首页</a></td><td>建议阅读顺序与总览</td></tr><tr><td><a href="/ultra_guides/manual/model-link">模型</a></td><td>连接、参数、测连与排错</td></tr><tr><td><a href="/ultra_guides/free-cloud/">免费云端</a></td><td>各厂商免费额度与填 Key</td></tr><tr><td><a href="/ultra_guides/local/">部署本地模型</a></td><td>语言 / 生图本机部署</td></tr><tr><td><a href="/ultra_guides/manual/chara-card">角色</a></td><td>导入、编辑、开聊</td></tr><tr><td><a href="/ultra_guides/manual/chat">聊天</a></td><td>对话与会话设置</td></tr><tr><td><a href="/ultra_guides/manual/lorebook">进阶</a></td><td>世界书、正则、人设、备份</td></tr></tbody></table><p>App 内：设置 → <strong>帮助与反馈</strong> → <strong>用户手册</strong>。</p><h2 id="常见问题-摘要" tabindex="-1">常见问题（摘要） <a class="header-anchor" href="#常见问题-摘要" aria-label="Permalink to &quot;常见问题（摘要）&quot;">​</a></h2><p><strong>Q：MiniTavern Ultra 是什么？</strong><br> A：一款 AI 角色扮演聊天应用。你可以创造属于自己的 AI 伙伴，也可以导入角色卡入戏扮演；用你自己的 API Key 或本地模型对话。</p><p><strong>Q：数据会上传到你们服务器吗？</strong><br> A：聊天、角色与密钥等默认保存在本机；调用模型时请求发往你配置的第三方或本地地址。详见 <a href="/ultra_guides/privacy">隐私协议</a>。</p><p><strong>Q：没有 API 也能玩吗？</strong><br> A：需要自行准备云端 Key，或按 <a href="/ultra_guides/local/">部署本地模型</a> 在电脑上搭建后再连接手机。常见免费额度见 <a href="/ultra_guides/free-cloud/">免费云端</a>；本机生图见 <a href="/ultra_guides/local/image-gen/">生图模型部署</a>。</p><h2 id="下载与政策" tabindex="-1">下载与政策 <a class="header-anchor" href="#下载与政策" aria-label="Permalink to &quot;下载与政策&quot;">​</a></h2><ul><li>顶栏 <strong>下载 MiniTavern</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">产品官网</a></li><li><a href="/ultra_guides/privacy">隐私协议</a> · <a href="/ultra_guides/terms">服务条款</a></li></ul>',22)])])}const f=r(n,[["render",o]]);export{_ as __pageData,f as default};
